1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import type {SessionStore} from '../../types/sessionStore.js';
5	import {ErrorCodes} from '../../types/messages.js';
6	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
55	    }
56	    // A history request is not a turn: answered here, outside the lock, so it never queues behind a streaming answer.
57	    if (validation.valid && validation.data.type === 'list_sessions') {
58	      const message: ListSessionsMessage = validation.data;
59	      return wsErrorHandler(ws, () => handleListSessions(ws, session, sessionStore, message));
60	    }
61	    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
62	  };
63	}
64	
65	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
66	async function answerInTurn(
67	  ws: WebSocket,
68	  session: ChatSession,
69	  orchestrator: ChatOrchestrator,
70	  validation: ValidationResult,
71	  signal: AbortSignal | undefined
72	): Promise<void> {
73	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
74	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
75	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
76	    return;
77	  }
78	  const startedAt = Date.now();
79	  try {
80	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
81	  } finally {
82	    endTurn(ws, session, signal, startedAt);
83	  }
84	}
85	
86	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
87	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
88	  if (signal?.aborted) {
89	    log.info('message', 'turn abandoned: its socket closed', {
90	      sessionId: session.sessionId,
91	      elapsedMs: Date.now() - startedAt,
92	    });
93	    return;
94	  }
95	  sendStreamEnd(ws);
96	}
97	
98	async function answerUserMessage(
99	  ws: WebSocket,
100	  session: ChatSession,
101	  orchestrator: ChatOrchestrator,
102	  validation: ValidationResult,
103	  signal: AbortSignal | undefined
104	): Promise<void> {
105	  const message = validation.valid ? validation.data : undefined;
106	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
107	  answerFrame(ws, validation);
108	}
109	
110	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
111	  if (!validation.valid) {
112	    log.warn('message', 'validation failed', {error: validation.error});
113	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
114	    return;
115	  }
116	
117	  const message = validation.data;
118	  if (message.type === 'ping') handlePing(ws, message.timestamp);
119	}
120	
121	// The user listed is the connection's own, read from the session: a frame naming another user lists no one else.
122	async function handleListSessions(
123	  ws: WebSocket,
124	  session: ChatSession,
125	  sessionStore: SessionStore | undefined,
126	  message: ListSessionsMessage
127	): Promise<void> {
128	  if (!sessionStore?.listFor) {
129	    sendSessionList(ws, []);
130	    return;
131	  }
132	  try {
133	    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
134	    sendSessionList(ws, summaries);
135	  } catch (error) {
136	    const detail = error instanceof Error ? error.message : 'Unknown error';
137	    log.error('ws', 'listing sessions failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
138	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
139	  }
140	}
141	
142	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
143	function isUserMessageFrame(rawMessage: unknown): boolean {
144	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
145	}
146	
147	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
148	  try {
149	    await action();
150	  } catch (error) {
151	    const message = error instanceof Error ? error.message : 'Unknown error';
152	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
153	    log.error('message', 'handling error', {error: message, code});
154	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
155	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
156	      return;
157	    }
158	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
159	  }
160	}
161	
162	async function handleUserMessage(
163	  ws: WebSocket,
164	  session: ChatSession,
165	  orchestrator: ChatOrchestrator,
166	  content: string,
167	  signal: AbortSignal | undefined
168	): Promise<void> {
169	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
170	
171	  const userEntry = createUserEntry(content);
172	  const userIndex = appendEntry(session, userEntry);
173	  sendUpsert(ws, userIndex, userEntry);
174	
175	  const parser = new ThinkingTagParser();
176	  const state: StreamState = {
177	    thinkingIndex: null,
178	    assistantIndex: null,
179	    suppressOutput: false,
180	    sentAssistantIndices: [],
181	  };
182	
183	  let textChunkCount = 0;
184	
185	  try {
186	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
187	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
188	      if (signal?.aborted) break;
189	      textChunkCount = logChunk(chunk, textChunkCount);
190	      processChunk(ws, session, state, parser, chunk);
191	    }
192	  } finally {
193	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
194	    flushHeldText(ws, session, state, parser);
195	    closeCutOff(ws, session, state, 'thinkingIndex');
196	    closeCutOff(ws, session, state, 'assistantIndex');
197	  }
198	
199	  if (textChunkCount > 0) {
200	    log.debug('stream', `received ${textChunkCount} text chunks`);
201	  }
202	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
203	}
204	
205	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
206	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
207	  if (chunk.type === 'text') return textChunkCount + 1;
208	
209	  if (textChunkCount > 0) {
210	    log.debug('stream', `received ${textChunkCount} text chunks`);
211	  }
212	
213	  if (chunk.type === 'tool_result') {
214	    log.debug('stream', 'tool_result chunk', {
215	      messageCount: chunk.clientMessages.length,
216	      types: chunk.clientMessages.map(m => m.type),
217	    });
218	    return 0;
219	  }
220	
221	  log.debug('stream', 'chunk', {type: chunk.type});
222	  return 0;
223	}
224	
225	function processChunk(
226	  ws: WebSocket,
227	  session: ChatSession,
228	  state: StreamState,
229	  parser: ThinkingTagParser,
230	  chunk: MessageChunk
231	): void {
232	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
233	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
234	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
235	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
236	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
237	}
238	
239	function processTextChunk(
240	  ws: WebSocket,
241	  session: ChatSession,
242	  state: StreamState,
243	  parser: ThinkingTagParser,
244	  text: string
245	): void {
246	  const segments = parser.push(text);
247	  for (const segment of segments) {
248	    handleTextSegment(ws, session, state, segment);
249	  }
250	}
251	
252	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
253	  if (segment.type === 'thinking') {
254	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
255	    return;
256	  }
257	  commitAndClear(ws, session, state, 'thinkingIndex');
258	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
259	}
260	
261	function streamSegment(
262	  ws: WebSocket,
263	  session: ChatSession,
264	  state: StreamState,
265	  key: StateIndexKey,
266	  createEntry: EntryFactory,
267	  content: string
268	): void {
269	  const isNew = initSegment(session, state, key, createEntry);
