// Question: when a client sends two frames back to back, do both 'message' events
// fire inside one server data callback (before microtasks drain)?
import {WebSocketServer, WebSocket} from 'ws';

const wss = new WebSocketServer({port: 0});
const order = [];

wss.on('connection', ws => {
  let microtaskRan = false;
  ws.on('message', raw => {
    order.push(`msg:${String(raw)} microtaskRanBefore=${microtaskRan}`);
    queueMicrotask(() => {
      microtaskRan = true;
      order.push('microtask');
    });
  });
});

const ws = new WebSocket(`ws://127.0.0.1:${wss.address().port}`);
ws.on('open', () => {
  ws.send('frame-one');
  ws.send('frame-two');
});
ws.on('close', () => {
  wss.close();
  console.log(order.join('\n'));
  process.exit(0);
});
setTimeout(() => {
  console.log('TIMEOUT\n' + order.join('\n'));
  process.exit(1);
}, 3000);

